dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ бит_ЛицевыеСчета.Ссылка КАК ЛицевойСчет, ВЫБОР КОГДА бит_ЛицевыеСчета.ИдентификаторЖКУ <> "" ТОГДА бит_ЛицевыеСчета.ИдентификаторЖКУ КОГДА бит_ЛицевыеСчета.ЕЛСГИСЖКХ <> "" ТОГДА бит_ЛицевыеСчета.ЕЛСГИСЖКХ ИНАЧЕ бит_ЛицевыеСчета.Наименование КОНЕЦ КАК НомерЛС, бит_ЛицевыеСчета.Здание КАК Здание, бит_СписокЗданий.ПочтовыйАдрес КАК ПочтовыйАдрес, бит_СписокЗданий.КадастровыйНомер КАК КадастровыйНомер, бит_ЛицевыеСчета.Квартира КАК Квартира ПОМЕСТИТЬ ВТ_ЛицевыеСчетаОбщая ИЗ Справочник.бит_ЛицевыеСчета КАК бит_ЛицевыеСчета ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_СписокЗданий КАК бит_СписокЗданий ПО бит_ЛицевыеСчета.Здание = бит_СписокЗданий.Ссылка ГДЕ бит_ЛицевыеСчета.Архивный = ЛОЖЬ И НЕ бит_ЛицевыеСчета.ПометкаУдаления И НЕ бит_СписокЗданий.ПометкаУдаления {ГДЕ (бит_ЛицевыеСчета.Ссылка В (&СписокЛС)), (бит_ЛицевыеСчета.Организация = &ОтборОрганизация), (бит_СписокЗданий.Улица В (&СписокУлиц)), (бит_ЛицевыеСчета.Здание В (&СписокЗданий)), (ВЫБОР КОГДА &ТипДомаГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.МКД) ТОГДА бит_СписокЗданий.ТипыДомовГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.МКД) ИЛИ бит_СписокЗданий.ТипыДомовГИСЖКХ = ЗНАЧЕНИЕ(Перечисление.бит_ТипыДомовГИСЖКХ.ПустаяСсылка) ИНАЧЕ бит_СписокЗданий.ТипыДомовГИСЖКХ В (&ТипДомаГИСЖКХ) КОНЕЦ)}
ИНДЕКСИРОВАТЬ ПО ЛицевойСчет, Здание, Квартира ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ЛицевыеСчетаОбщая.ЛицевойСчет КАК ЛицевойСчет, ВТ_ЛицевыеСчетаОбщая.НомерЛС КАК НомерЛС, ВТ_ЛицевыеСчетаОбщая.Здание КАК Здание, ВТ_ЛицевыеСчетаОбщая.ПочтовыйАдрес + " " КАК ПочтовыйАдрес, ВТ_ЛицевыеСчетаОбщая.КадастровыйНомер КАК КадастровыйНомер, ВТ_ЛицевыеСчетаОбщая.Квартира КАК Квартира, бит_Квартиры.КадастровыйНомер КАК КадастровыйНомерКвартиры ПОМЕСТИТЬ ВТ_ЛицевыеСчета ИЗ ВТ_ЛицевыеСчетаОбщая КАК ВТ_ЛицевыеСчетаОбщая ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_Квартиры КАК бит_Квартиры ПО ВТ_ЛицевыеСчетаОбщая.Квартира = бит_Квартиры.Ссылка ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗЛИЧНЫЕ ВТ_ЛицевыеСчета.Здание КАК Здание, ВТ_ЛицевыеСчета.ПочтовыйАдрес КАК ПочтовыйАдрес, ВТ_ЛицевыеСчета.КадастровыйНомер КАК КадастровыйНомер ПОМЕСТИТЬ ВТ_Здания ИЗ ВТ_ЛицевыеСчета КАК ВТ_ЛицевыеСчета
ИНДЕКСИРОВАТЬ ПО Здание ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ бит_ГрупповыеСчетчикиСрезПоследних.Услуга КАК Услуга, бит_ГрупповыеСчетчикиСрезПоследних.ГрупповойСчетчик КАК Счетчик, бит_ГрупповыеСчетчикиСрезПоследних.ЛицевойСчет КАК ЛицевойСчет, "Коллективный (общедомовой)" КАК ВидПУ ПОМЕСТИТЬ ВТ_ДанныеУстановкиПУ ИЗ РегистрСведений.бит_ГрупповыеСчетчики.СрезПоследних( &Период, ЛицевойСчет В (ВЫБРАТЬ РАЗЛИЧНЫЕ ВТ_ЛицевыеСчета.ЛицевойСчет ИЗ ВТ_ЛицевыеСчета КАК ВТ_ЛицевыеСчета)) КАК бит_ГрупповыеСчетчикиСрезПоследних ГДЕ бит_ГрупповыеСчетчикиСрезПоследних.Использовать
ИНДЕКСИРОВАТЬ ПО Счетчик, бит_ГрупповыеСчетчикиСрезПоследних.ЛицевойСчет ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ДанныеУстановкиПУ.Услуга КАК Услуга, ВТ_ДанныеУстановкиПУ.Счетчик КАК Счетчик, ВТ_ДанныеУстановкиПУ.ЛицевойСчет КАК ЛицевойСчет, ВТ_ЛицевыеСчета.НомерЛС КАК НомерЛС, ВТ_ЛицевыеСчета.ПочтовыйАдрес КАК ПочтовыйАдрес, ВТ_ДанныеУстановкиПУ.ВидПУ КАК ВидПУ ПОМЕСТИТЬ ВТ_ИтоговаяТаблица ИЗ ВТ_ДанныеУстановкиПУ КАК ВТ_ДанныеУстановкиПУ ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЛицевыеСчета КАК ВТ_ЛицевыеСчета ПО ВТ_ДанныеУстановкиПУ.ЛицевойСчет = ВТ_ЛицевыеСчета.ЛицевойСчет
ИНДЕКСИРОВАТЬ ПО Счетчик ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ЕСТЬNULL(ВТ_ИтоговаяТаблица.ЛицевойСчет, "") КАК ЛицевойСчет, ЕСТЬNULL(ВТ_ИтоговаяТаблица.Счетчик, "") КАК Счетчик, ЕСТЬNULL(ВТ_ИтоговаяТаблица.Счетчик.Код, "") КАК СсылочныйНомерПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ПочтовыйАдрес, "") КАК АдресДома, ЕСТЬNULL(бит_Счетчики.ЗаводскойСерийныйНомерПУ, "") КАК ЗаводскойСерийныйНомерПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидПУ, "") КАК ВидПУ, ЕСТЬNULL(бит_Счетчики.МаркаПУ, "") КАК МаркаПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.НомерЛС, "") КАК НомерЛС ИЗ ВТ_ИтоговаяТаблица КАК ВТ_ИтоговаяТаблица ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_Счетчики КАК бит_Счетчики ПО ВТ_ИтоговаяТаблица.Счетчик = бит_Счетчики.Ссылка
